    return `<div class="child-profile"><img class="child-portrait-large" src="${childPortrait(s, c2)}" alt="${esc19(displayNames(c2.name))}" width="320" height="320"><span class="eyebrow">${esc19(childTitleLabel(c2))}</span><h2>${childName(c2)}</h2>${childLabel(c2)}<p>${childAgeLabel(s, c2)}</p><div class="child-stages" aria-label="Bốn giai đoạn trưởng thành">${CHILD_STAGES.map(([, name], i) => `<span class="${i === stage ? "current" : i < stage ? "passed" : ""}">${name}</span>`).join("")}</div><p class="tip">${esc19(childNextMilestone(s, c2))}</p><p class="footnote">${c2.royal === false ? "Phụ thân" : "Phụ hoàng"}: ${esc19(c2.father)}<br>${c2.adoption ? `${c2.adoption.kind === "godchild" ? "Mẫu thân đỡ đầu" : "Dưỡng mẫu"}: ${esc19(displayNames(s.p.name))}<br>Mẹ ruột: ${esc19(c2.adoption.mother.title + " " + c2.adoption.mother.name)}` : `Mẫu thân: ${esc19(displayNames(s.p.name))}`}</p><ol class="child-timeline"><li><b>Chào đời</b><span>${c2.month < 0 ? "Trước khi nàng nhập cung" : `Tháng ${c2.month % 12 + 1} · Năm ${Math.floor(c2.month / 12) + 1}`}</span></li>${c2.milestones.map((m) => `<li><b>${esc19(m.title)}</b><span>${Math.floor((m.month - c2.month) / 12)} tuổi</span></li>`).join("")}</ol></div>`;
