    updateMarkup($("#app"), header() + `<div class="scroll-area">${page === "home" ? home() : page === "map" ? mapPage() : page === "bag" ? bag() : page === "people" ? people() : legacy()}</div>` + nav());
    $(".scroll-area").scrollTop = scroll;
