    if (beginImperialSecret(s)) save();
    const next = s.imperialSecret?.scene ? "imperial-secret" : s.result?.theme === "lake-ambush" ? "result" : pendingFemaleNotice(s)?.beforeEnding ? "female-notice" : s.dateScene ? "date-scene" : s.entryStory ? "entry-story" : s.intro ? openIntro ? "intro" : null : s.notices.some((n) => n.kind === "dowry") ? "dowry" : s.imperialNight ? "imperial-night" : s.lake ? "lake" : s.wishingPool ? "wishing-pool" : s.coronation ? "coronation" : s.festival ? "festival" : s.guqin ? "guqin" : s.caro ? "caro" : s.tea ? "tea" : s.notices.some((n) => n.kind === "rank-decree") ? "rank-decree" : s.result?.theme === "imperial" ? "result" : s.result && s.notices.some((n) => n.kind === "sisterhood") ? "result" : pendingFemaleNotice(s) ? "female-notice" : s.notices.some((n) => !["adoption-decree", "dowry"].includes(n.kind)) ? "rewards" : s.notices.some((n) => n.kind === "adoption-decree") ? "adoption-decree" : !s.p.alive ? "death" : s.decree ? "decree" : s.mini ? "memory" : s.exam ? "exam" : s.story ? "court-story" : s.result ? "result" : s.event ? "event" : s.adoptionChoice ? "adoption-choice" : fashionReady(s) ? "fashion" : pendingSideEvent(s) ? "side-event" : sisterEventReady(s) ? "sister-event" : null;
    if (renderNow) show(next);
